def clean(df):
    df = df.copy()
    # drop exact duplicate rows (e.g. repeated Order_ID 2005)
    df = df.drop_duplicates()
    # fix category spelling variants so groups merge correctly
    df['Category'] = df['Category'].replace({
        'Office Suplies': 'Office Supplies',
        'Furnture': 'Furniture'
    })
    # drop invalid records with non-positive quantity
    df = df[df['Quantity'] >= 1]
    return df

def answer(df):
